def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_threats = 0
    urgent_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget:
                rich_threats += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    abundance = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)

    emergency = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if emergency:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
        if supply >= 22:
            bid *= 0.92
        return max(0.0, min(budget, bid))

    if highest_prev >= 120:
        if supply <= 18 and hp >= 6 and no_water_days == 0:
            return max(0.0, min(budget, DAILY_SALARY * 0.08))
        bid = DAILY_SALARY * (0.42 + 0.18 * scarcity)
        if pressured:
            bid = max(bid, DAILY_SALARY * 0.72)
        return max(0.0, min(budget, bid))

    base = 22.0 + 12.0 * scarcity + 8.0 * urgent_opp + 6.0 * rich_threats

    if supply >= 23:
        base -= 10.0
    elif supply >= 20:
        base -= 4.0

    if highest_prev > 0:
        if highest_prev <= 85:
            base = max(base, highest_prev + 2.0)
        else:
            base = max(base, avg_prev * 0.6)

    if pressured:
        base += 18.0
    if hp >= 8 and no_water_days == 0 and supply <= 17:
        base -= 8.0

    if day >= 8:
        base += 10.0

    bid = max(1.0, base)
    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((k, o))

    if not alive_opps:
        cap = DAILY_SALARY * 0.4
        return max(0.0, min(budget, cap))

    # Extract yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: if supply is low, bid more to avoid missing water.
    # If supply is high, bid less (water more likely to be allocated).
    if supply <= (MIN_SUPPLY + WATER_REQ):
        supply_factor = 0.85
    elif supply >= (MAX_SUPPLY - 1.0):
        supply_factor = 0.55
    else:
        supply_factor = 0.7

    # Our urgency: if we have gone without water, increase bid.
    if no_water_days >= 2 or hp <= 2:
        urgency_factor = 0.95
    elif no_water_days == 1 or hp <= 4:
        urgency_factor = 0.8
    else:
        urgency_factor = 0.65

    # Opponent aggression: if yesterday bids were very high, slightly raise.
    # Otherwise keep moderate to preserve budget.
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        aggression_factor = 0.95
    elif highest_prev_bid >= DAILY_SALARY * 1.0:
        aggression_factor = 0.8
    else:
        aggression_factor = 0.65

    target = DAILY_SALARY * supply_factor * urgency_factor * aggression_factor

    # If we know someone was bidding near our salary, nudge above average but not too high.
    if yesterday_bids:
        target = max(target, avg_prev_bid * 0.75)

    # Safety cap: never exceed budget; also avoid reckless bids.
    # With medium scenario, keep within 0.75 of daily salary unless very urgent.
    if urgency_factor < 0.85:
        max_bid = DAILY_SALARY * 0.75
    else:
        max_bid = DAILY_SALARY * 1.05

    bid = min(budget, max_bid, target)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
